result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/auditlog/src/auditlog/journal.py", "content": """"Tamper-evident, append-only accounting journal.

Record layout (one JSON object per line):

    {"seq": 1,
     "timestamp": "2026-08-24T12:00:00.000000+00:00",
     "entry": {"lines": [{"account": "cash", "debit": 500, "credit": 0}, ...]},
     "prev_hash": "<hex or GENESIS>",
     "hash": "<hex>"}

    hash = sha256(canonical_json(record_without_hash))

Canonical serialization: sorted keys, separators (",", ":"), UTF-8,
ensure_ascii=False -> byte-for-byte deterministic regardless of dict order
or whitespace variance in the stored line.
"""

from __future__ import annotations

import hashlib
import json
import os
from datetime import datetime, timezone
from pathlib import Path

GENESIS = "GENESIS"


class CorruptEntry(ValueError):
    """Raised for entries that violate double-entry balance."""


# ---------------------------------------------------------------- canonical

def canonical_bytes(obj) -> bytes:
    """Deterministic serialization: sorted keys, no insignificant whitespace."""
    return json.dumps(
        obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def compute_hash(record: dict) -> str:
    payload = {k: v for k, v in record.items() if k != "hash"}
    return hashlib.sha256(canonical_bytes(payload)).hexdigest()


# ------------------------------------------------------------- entry checks

def validate_entry(entry: dict) -> None:
    """Double-entry invariant: sum(debit cents) == sum(credit cents)."""
    lines = entry.get("lines")
    if not isinstance(lines, list) or not lines:
        raise CorruptEntry("entry must contain a non-empty 'lines' list")
    debits = credits = 0
    for ln in lines:
        if not isinstance(ln, dict) or not isinstance(ln.get("account"), str):
            raise CorruptEntry(f"malformed line: {ln!r}")
        d, c = ln.get("debit", 0), ln.get("credit", 0)
        if not (isinstance(d, int) and isinstance(c, int)) or d < 0 or c < 0:
            raise CorruptEntry(f"debit/credit must be non-negative ints: {ln!r}")
        debits += d
        credits += c
    if debits != credits:
        raise CorruptEntry(
            f"unbalanced entry: debits={debits} != credits={credits}"
        )


# ------------------------------------------------------------------ journal

class Journal:
    """Append-only, hash-chained JSONL journal with torn-write recovery."""

    def __init__(self, path: str | os.PathLike):
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._recover_torn_tail()
        self._records = self._load()
        self.seq = self._records[-1]["seq"] if self._records else 0
        self.prev_hash = self._records[-1]["hash"] if self._records else GENESIS

    # -- recovery ----------------------------------------------------------

    def _recover_torn_tail(self) -> None:
        """A final line without a terminating newline is a torn write.

        Truncate it to the end of the last complete record so appends
        continue from a consistent state. Fully-written-but-corrupt lines
        are left alone; verify() is responsible for reporting those.
        """
        if not self.path.exists() or self.path.stat().st_size == 0:
            return
        data = self.path.read_bytes()
        if data.endswith(b"\n"):
            return
        cut = data.rfind(b"\n")
        new_end = cut + 1 if cut >= 0 else 0
        with open(self.path, "r+b") as f:
            f.truncate(new_end)
            f.flush()
            os.fsync(f.fileno())

    def _load(self) -> list[dict]:
        records = []
        if not self.path.exists():
            return records
        with open(self.path, "r", encoding="utf-8") as f:
            for raw in f:
                raw = raw.strip()
                if not raw:
                    continue
                records.append(json.loads(raw))
        return records

    # -- appending ---------------------------------------------------------

    def append(self, entry: dict, timestamp: str | None = None) -> dict:
        validate_entry(entry)
        self.seq += 1
        ts = timestamp or datetime.now(timezone.utc).isoformat()
        record = {
            "seq": self.seq,
            "timestamp": ts,
            "entry": entry,
            "prev_hash": self.prev_hash,
        }
        record["hash"] = compute_hash(record)
        with open(self.path, "a", encoding="utf-8") as f:
            f.write(canonical_bytes(record).decode("utf-8") + "\n")
            f.flush()
            os.fsync(f.fileno())
        self._records.append(record)
        self.prev_hash = record["hash"]
        return record

    @property
    def records(self) -> list[dict]:
        return list(self._records)

    def __len__(self) -> int:
        return len(self._records)


# ----------------------------------------------------------------- verify

def verify(path: str | os.PathLike) -> dict:
    """Replay the file and check seq continuity, hash chain and integrity.

    Returns {"ok": True} or {"ok": False, "error": ..., "seq": <first bad>}.
    """
    expected_seq = 0
    prev_hash = GENESIS
    try:
        with open(path, "r", encoding="utf-8") as f:
            for lineno, raw in enumerate(f, start=1):
                raw = raw.strip()
                if not raw:
                    continue
                try:
                    rec = json.loads(raw)
                    expected_seq += 1
                    seq = rec["seq"]
                except Exception as exc:
                    return {
                        "ok": False,
                        "error": f"line {lineno}: unparseable JSON ({exc})",
                        "seq": expected_seq + 1,
                    }
                if seq != expected_seq:
                    return {
                        "ok": False,
                        "error": f"expected seq {expected_seq}, found {seq}",
                        "seq": seq,
                    }
                if rec.get("prev_hash") != prev_hash:
                    return {
                        "ok": False,
                        "error": f"broken chain at seq {seq}",
                        "seq": seq,
                    }
                if compute_hash(rec) != rec.get("hash"):
                    return {
                        "ok": False,
                        "error": f"hash mismatch at seq {seq}",
                        "seq": seq,
                    }
                try:
                    validate_entry(rec["entry"])
                except CorruptEntry as exc:
                    return {
                        "ok": False,
                        "error": f"unbalanced ledger at seq {seq}: {exc}",
                        "seq": seq,
                    }
                prev_hash = rec["hash"]
    except FileNotFoundError:
        pass
    return {"ok": True}
